Properties p = new Properties();
p.put(StreamsConfig.APPLICATION_ID_CONFIG, "order-summary");   // = 컨슈머 그룹 ID
p.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "kafka-1:19092");
p.put(StreamsConfig.PROCESSING_GUARANTEE_CONFIG, StreamsConfig.EXACTLY_ONCE_V2);
p.put(StreamsConfig.NUM_STREAM_THREADS_CONFIG, 2);

StreamsBuilder builder = new StreamsBuilder();

KStream<String, OrderEvent> orders =
        builder.stream("orders", Consumed.with(Serdes.String(), orderSerde));

orders.filter((k, v) -> v.amount() > 0)
      .mapValues(OrderSummary::from)
      .peek((k, v) -> log.debug("{} -> {}", k, v))
      .to("order-summary", Produced.with(Serdes.String(), summarySerde));

KafkaStreams streams = new KafkaStreams(builder.build(), p);
Runtime.getRuntime().addShutdownHook(new Thread(streams::close));
streams.start();
